WITH valid AS (SELECT id, email, dept_id, job_title, salary, is_remote, REPLACE(full_name, ' ', '') AS full_name_slug, ROUND(salary, 2) AS salary_rounded, COALESCE(job_title, 'DIRECT') AS resolved_job_title FROM employees WHERE hire_date >= DATE '2023-05-23' AND salary > 145000) SELECT d.dept_name, s.job_title, COUNT(*) AS num_rows, SUM(s.salary_rounded) AS total_salary_rounded FROM valid s LEFT JOIN departments d ON s.dept_id = d.id GROUP BY GROUPING SETS ((d.dept_name, s.job_title), (d.dept_name)) ORDER BY num_rows NULLS FIRST
